import { Composio } from "@composio/core";

async function main() {
    try {
        const composio = new Composio({
            apiKey: process.env.COMPOSIO_API_KEY || "dummy-key",
        });

        const session = composio.client.getSession("zealt-user01");
        const connectionRequest = await session.authorize('github');

        if (connectionRequest && connectionRequest.redirectUrl) {
            console.log(connectionRequest.redirectUrl);
        } else {
            console.error("Failed to get redirect URL");
        }
    } catch (error) {
        console.error("Error:", error);
    }
}

main();

